/*
 * BL616 MOD->PCM->HDMI. The Apple IIgs DOC and its sound RAM are uninvolved.
 * Audio is generated by public-domain HxCMOD at exactly HDMI's 44,100 Hz.
 * SPI XFER SPACE 6 writes one 16-bit LE left/right pair per 4 bytes.
 *
 * IMPORTANT: the original NTP player is intentionally NOT included.
 * No 6502 mailbox, native DOC register writes, DOC oscillator patches,
 * sound sample-bank generation, or NTP instrument translation.
 */
#include "mcu_mod_audio.h"
#include "mcu_mod_jukebox.h"
#include "mcu_mod_format.h"
#include "mod_filename.h"
#include "mcu_mod_sample_store.h"
#include "mcu_mod_pattern_store.h"
#include "mcu_mod_gain.h"
#include "mcu_mod_now_playing.h"
#include "third_party/hxcmod/hxcmod.h"
#include "fpga_spi.h"
#include "disk.h"
#include "osd_console.h"
#include "FreeRTOS.h"
#include "task.h"
#include "usb_osal.h"
#include "bflb_mtimer.h"
#include <ctype.h>
#include <string.h>

#define PCM_SPACE 6u
#define PCM_CTRL_RESET 0x800000u
#define PCM_CTRL_ENABLE 0x800001u
#define PCM_STATUS 0x800000u
#define PCM_BLOCK_FRAMES 256u
#define PCM_BLOCK_BYTES (PCM_BLOCK_FRAMES*4u)
#define MOD_FILE_LIMIT MOD_TOTAL_FILE_MAX
#define PCM_HZ 44100u
#define MOD_STAGE_BYTES 4096u   /* FAT/SDRAM staging independent of cache size */
#define PCM_FIFO_FRAMES 2048u
#define MOD_PATH_CAP 128u

static modcontext s_ctx;
static msample s_pcm[PCM_BLOCK_FRAMES*2u];
static uint8_t s_status[16];
/* Entire MOD header is held in fixed SRAM; all patterns live in FPGA.
 * No contiguous MCU heap allocation is required regardless of MOD length. */
static uint8_t s_mod_header[MOD_HEADER_PROBE];
static uint8_t s_mod_transfer[MOD_STAGE_BYTES];
static uint8_t s_mod_stage_head[32],s_mod_stage_tail[32];
static uint8_t s_pat_stage_head[32],s_pat_stage_tail[32];
static volatile uint32_t s_path_seq;
static uint32_t s_seen_seq;
static char s_path[MOD_PATH_CAP];
static volatile uint32_t s_stop;
static volatile uint32_t s_replay;
static char s_last_request[MOD_PATH_CAP]; // written by modpcm task alone
static volatile uint32_t s_has_last;      // published after full path copy
static volatile mod_pcm_status_t s_state=MOD_PCM_IDLE;
/* J1 control mailbox: producer(s) publish directory and mode as a seqlock;
 * only the MOD task performs scanning, allocation and all HxCMOD calls. */
static char s_juke_path[MOD_PATH_CAP];
/* Atomic with s_juke_path under the existing request seqlock. Empty means
 * original "begin at sorted index zero" behavior. */
static char s_juke_start_file[MOD_PATH_CAP];
static volatile uint32_t s_juke_seq, s_juke_seen, s_juke_recursive;
static volatile uint32_t s_juke_count_pub, s_nav, s_once, s_resume;
static volatile uint32_t s_juke_last_track_pub; /* 1-based last started playlist track */
static volatile uint32_t s_juke_generation;
static volatile mod_jukebox_scan_state_t s_juke_scan_state=MOD_JUKE_IDLE;
static void juke_state(mod_jukebox_scan_state_t state)
{
    __atomic_store_n(&s_juke_scan_state,state,__ATOMIC_RELEASE);
    __atomic_add_fetch(&s_juke_generation,1u,__ATOMIC_RELEASE);
}
static bool valid_path(const char *path); /* reused by file-start picker */
static void juke_publish(const char *dir,bool recursive,const char *start_file)
{
    /* Avoid two producers corrupting the request buffer. */
    uint32_t old;
    for(;;) {
        old=__atomic_load_n(&s_juke_seq,__ATOMIC_ACQUIRE);
        if(old&1u) {
            vTaskDelay(pdMS_TO_TICKS(1));
            continue;
        }
        if(__atomic_compare_exchange_n(&s_juke_seq,&old,old+1u,
                 false,__ATOMIC_ACQ_REL,__ATOMIC_ACQUIRE))
            break;
    }
    memset(s_juke_path,0,sizeof(s_juke_path));
    memcpy(s_juke_path,dir,strlen(dir)+1u);
    memset(s_juke_start_file,0,sizeof(s_juke_start_file));
    if(start_file)memcpy(s_juke_start_file,start_file,strlen(start_file)+1u);
    s_juke_recursive=recursive?1u:0u;
    /* Publish QUEUED before unlocking the request seqlock: the MOD task
     * must not publish SCANNING/READY and then lose it to a late QUEUED. */
    juke_state(MOD_JUKE_QUEUED);
    __atomic_store_n(&s_juke_seq,old+2u,__ATOMIC_RELEASE);
}
static bool take_juke(char out[MOD_PATH_CAP],bool *recursive,
                      char start_file[MOD_PATH_CAP])
{
    uint32_t a=__atomic_load_n(&s_juke_seq,__ATOMIC_ACQUIRE);
    if(!a || (a&1u) || a==s_juke_seen)return false;
    memcpy(out,s_juke_path,MOD_PATH_CAP);
    memcpy(start_file,s_juke_start_file,MOD_PATH_CAP);
    const bool r=s_juke_recursive!=0;
    uint32_t end=__atomic_load_n(&s_juke_seq,__ATOMIC_ACQUIRE);
    if(a!=end || (end&1u))return false;
    s_juke_seen=end;
    *recursive=r;
    return true;
}
bool mod_audio_jukebox_start(const char *dir,bool recursive)
{
    if(!dir || strlen(dir)>=MOD_PATH_CAP || strstr(dir,"..") ||
       dir[0]=='/' || strchr(dir,':') || strchr(dir,'\\'))return false;
    juke_publish(dir,recursive,NULL);
    return true;
}
/* Scan only the selected MOD's parent folder; begin at its sorted index
 * and finish at the end of that folder (never silently wrap to track 1).
 * This requires no FLASH writes: user can choose a restart point any day. */
bool mod_audio_jukebox_start_from_file(const char *file)
{
    if(!valid_path(file))return false;
    char dir[MOD_PATH_CAP];
    const char *slash=strrchr(file,'/');
    const size_t len=slash ? (size_t)(slash-file):0u;
    if(len>=sizeof(dir))return false;
    memcpy(dir,file,len);
    dir[len]=0;
    juke_publish(dir,false,file);
    return true;
}
void mod_audio_jukebox_from_last(bool recursive)
{
    /* Sentinel 0x01 is not a valid user directory name. */
    juke_publish("\001",recursive,NULL);
}
bool mod_audio_jukebox_resume(void)
{
    /* Same-session shortcut; no flash wear, restarts last heard track at
     * its beginning. After MCU reboot use picker "START AT FILE". */
    if(!__atomic_load_n(&s_juke_count_pub,__ATOMIC_ACQUIRE) ||
       __atomic_load_n(&s_juke_scan_state,__ATOMIC_ACQUIRE)!=MOD_JUKE_READY ||
       s_state!=MOD_PCM_STOPPED)
        return false;
    __atomic_store_n(&s_resume,1u,__ATOMIC_RELEASE);
    return true;
}
bool mod_audio_next(void)
{
    if(!__atomic_load_n(&s_juke_count_pub,__ATOMIC_ACQUIRE))return false;
    __atomic_store_n(&s_nav,1u,__ATOMIC_RELEASE);
    return true;
}
bool mod_audio_previous(void)
{
    if(!__atomic_load_n(&s_juke_count_pub,__ATOMIC_ACQUIRE))return false;
    __atomic_store_n(&s_nav,2u,__ATOMIC_RELEASE);
    return true;
}
void mod_audio_set_play_once(bool once)
{
    __atomic_store_n(&s_once,once?1u:0u,__ATOMIC_RELEASE);
}
bool mod_audio_play_once(void)
{
    return __atomic_load_n(&s_once,__ATOMIC_ACQUIRE)!=0u;
}
unsigned mod_audio_jukebox_count(void)
{
    return __atomic_load_n(&s_juke_count_pub,__ATOMIC_ACQUIRE);
}
unsigned mod_audio_jukebox_last_track(void)
{
    return __atomic_load_n(&s_juke_last_track_pub,__ATOMIC_ACQUIRE);
}
mod_jukebox_scan_state_t mod_audio_jukebox_scan_state(void)
{
    return __atomic_load_n(&s_juke_scan_state,__ATOMIC_ACQUIRE);
}
uint32_t mod_audio_jukebox_generation(void)
{
    return __atomic_load_n(&s_juke_generation,__ATOMIC_ACQUIRE);
}


static bool valid_path(const char *path)
{
    if(!path)return false;
    size_t n=strlen(path);
    if(n<5u || n>=MOD_PATH_CAP || strstr(path,"..") ||
       path[0]=='/' || strchr(path,':') || strchr(path,'\\'))return false;
    return mod_filename_matches(path);
}
bool mod_audio_choose(const char *path)
{
    if(!valid_path(path))return false;
    __atomic_add_fetch(&s_path_seq,1u,__ATOMIC_RELEASE);
    memset(s_path,0,sizeof s_path);
    memcpy(s_path,path,strlen(path)+1u);
    __atomic_add_fetch(&s_path_seq,1u,__ATOMIC_RELEASE);
    s_state=MOD_PCM_SELECTED;
    return true;
}
static bool take_pending(char out[MOD_PATH_CAP])
{
    uint32_t a=__atomic_load_n(&s_path_seq,__ATOMIC_ACQUIRE);
    if(!a || (a&1u) || a==s_seen_seq)return false;
    memcpy(out,s_path,MOD_PATH_CAP);
    uint32_t b=__atomic_load_n(&s_path_seq,__ATOMIC_ACQUIRE);
    if(a!=b || (b&1u))return false;
    s_seen_seq=b;
    return true;
}
mod_pcm_status_t mod_audio_status(void){return s_state;}
void mod_audio_request_stop(void)
{
    __atomic_store_n(&s_stop,1u,__ATOMIC_RELEASE);
}
bool mod_audio_replay_last(void)
{
    if(!__atomic_load_n(&s_has_last,__ATOMIC_ACQUIRE))
        return false;
    __atomic_store_n(&s_replay,1u,__ATOMIC_RELEASE);
    return true;
}
static bool pcm_read_status(void)
{
    fpga_spi_xfer_read(PCM_SPACE,PCM_STATUS,s_status,sizeof s_status);
    return s_status[0]==0x50 && s_status[1]==0x43 &&
           s_status[2]==1u;
}
static uint16_t pcm_free(void)
{
    return (uint16_t)s_status[6] | (uint16_t)((uint16_t)s_status[7]<<8);
}
static uint16_t pcm_underruns(void)
{
    return (uint16_t)s_status[8] | (uint16_t)((uint16_t)s_status[9]<<8);
}
static void pcm_control(uint32_t address,uint8_t value)
{
    fpga_spi_xfer_write(PCM_SPACE,address,&value,1u);
}
static void player_release(void)
{
    pcm_control(PCM_CTRL_ENABLE,0);
    pcm_control(PCM_CTRL_RESET,0xA5u);
    hxcmod_unload(&s_ctx);
    mod_patterns_invalidate();
    mod_store_invalidate();
}
/* J2R6: stage every pattern in a separate 256-KiB FPGA SDRAM bank;
 * the 2-KiB MCU active-pattern cache replaces the old 99+KiB heap
 * allocation that caused the 3EDGES freeze. Samples retain their entire
 * independent 2-MiB SDRAM bank. The original file-read order is preserved. */
static bool player_load(const char *path)
{
    fs_req_t fs;
    mod_format_t fmt;
    uint32_t off;
    bool ok=false,opened=false;
    memset(&fs,0,sizeof fs);
    fs.op=FSOP_MOD_OPEN;fs.path=path;
    if(disk_fs_request(&fs)!=0) {
        osd_log("MCU MOD: FILE OPEN FAILED");
        goto finish;
    }
    opened=true;
    const uint32_t file_size=fs.size;
    if(file_size<MOD_HEADER_PROBE || file_size>MOD_FILE_LIMIT) {
        osd_log("MCU MOD: FILE SIZE %lu UNSUPPORTED",
                (unsigned long)file_size);
        goto finish;
    }
    memset(&fs,0,sizeof fs);
    fs.op=FSOP_MOD_READ;
    fs.buf=s_mod_header;
    fs.len=MOD_HEADER_PROBE;
    if(disk_fs_request(&fs)!=0 || fs.out!=MOD_HEADER_PROBE) {
        osd_log("MCU MOD: HEADER READ FAILED");
        goto finish;
    }
    if(!mod_format_probe(s_mod_header,file_size,&fmt)) {
        osd_log("MCU MOD: BAD/UNSUPPORTED MOD FORMAT");
        goto finish;
    }
    if(!mod_store_begin(fmt.lengths) ||
       !mod_patterns_begin(fmt.channels,fmt.pattern_count) ||
       fmt.pattern_bytes!=mod_patterns_bytes()) {
        osd_log("MOD: FPGA PAT/SAMPLE CAPACITY ERROR");
        goto finish;
    }

    /* 15-instrument SoundTracker has a 600B header. The initial 1084B
     * probe already read the first 484B of pattern data; stage those
     * bytes without rereading them or misaligning the SD file cursor. */
    if(fmt.header_bytes<MOD_HEADER_PROBE) {
        const uint32_t preloaded=MOD_HEADER_PROBE-fmt.header_bytes;
        if(preloaded < sizeof s_pat_stage_head ||
           preloaded > fmt.pattern_bytes ||
           !mod_patterns_stage(0u,s_mod_header+fmt.header_bytes,
                               (uint16_t)preloaded)) {
            osd_log("MOD: EARLY PATTERN STAGE FAILED");
            goto finish;
        }
        memcpy(s_pat_stage_head,s_mod_header+fmt.header_bytes,
               sizeof s_pat_stage_head);
        off=MOD_HEADER_PROBE;
    } else {
        off=fmt.header_bytes;
    }
    /* Continue reading sequentially from the exact current FAT offset. */
    for(;off<fmt.prefix_bytes;) {
        const uint32_t rel=off-fmt.header_bytes;
        uint32_t len=fmt.prefix_bytes-off;
        if(len>MOD_STAGE_BYTES)len=MOD_STAGE_BYTES;
        memset(&fs,0,sizeof fs);
        fs.op=FSOP_MOD_READ;
        fs.buf=s_mod_transfer;
        fs.len=len;
        if(disk_fs_request(&fs)!=0 || fs.out!=len ||
           !mod_patterns_stage(rel,s_mod_transfer,(uint16_t)len)) {
            osd_log("MOD: FPGA PAT STAGE FAILED +%lu",
                    (unsigned long)rel);
            goto finish;
        }
        if(rel==0u)
            memcpy(s_pat_stage_head,s_mod_transfer,sizeof s_pat_stage_head);
        if(off+len==fmt.prefix_bytes)
            memcpy(s_pat_stage_tail,s_mod_transfer+len-
                   sizeof s_pat_stage_tail,sizeof s_pat_stage_tail);
        off+=len;
    }
    if(!mod_patterns_verify(0u,s_pat_stage_head,sizeof s_pat_stage_head) ||
       !mod_patterns_verify(fmt.pattern_bytes-sizeof s_pat_stage_tail,
                            s_pat_stage_tail,sizeof s_pat_stage_tail)) {
        osd_log("MOD: FPGA PAT READBACK FAILED");
        goto finish;
    }

    /* File cursor is now exactly at the first PCM sample; retain the
     * existing verified 2-MiB sample staging and sentinel checks. */
    const uint16_t verify_len=(uint16_t)(fmt.sample_bytes<32u ?
                                            fmt.sample_bytes : 32u);
    for(off=0;off<fmt.sample_bytes;) {
        uint32_t len=fmt.sample_bytes-off;
        if(len>MOD_STAGE_BYTES)len=MOD_STAGE_BYTES;
        memset(&fs,0,sizeof fs);
        fs.op=FSOP_MOD_READ;
        fs.buf=s_mod_transfer;
        fs.len=len;
        if(disk_fs_request(&fs)!=0 || fs.out!=len ||
           !mod_store_stage(off,s_mod_transfer,(uint16_t)len)) {
            osd_log("MCU MOD: SAMPLE STAGE FAILED +%lu",
                    (unsigned long)off);
            goto finish;
        }
        if(off==0u)memcpy(s_mod_stage_head,s_mod_transfer,verify_len);
        if(off+len==fmt.sample_bytes)
            memcpy(s_mod_stage_tail,s_mod_transfer+len-verify_len,verify_len);
        off+=len;
    }
    if(verify_len &&
       (!mod_store_verify(0u,s_mod_stage_head,verify_len) ||
        !mod_store_verify(fmt.sample_bytes-verify_len,
                          s_mod_stage_tail,verify_len))) {
        osd_log("MCU MOD: FPGA SDRAM READBACK FAILED");
        goto finish;
    }
    if(!hxcmod_init(&s_ctx) ||
       !hxcmod_setcfg(&s_ctx,PCM_HZ,100,1))goto finish;
    hxcmod_external_samples(&s_ctx,MOD_SDRAM_BASE,MOD_SDRAM_CAPACITY,
                            NULL,mod_store_read,mod_store_write);
    hxcmod_external_patterns(&s_ctx,fmt.pattern_bytes,
                             NULL,mod_patterns_get);
    /* HxCMOD copies its 1084-byte header; pattern accesses are always
     * redirected through mod_patterns_get, never header+pattern heap. */
    if(!hxcmod_load(&s_ctx,s_mod_header,MOD_HEADER_PROBE)) {
        osd_log("MCU MOD: HxCMOD REJECTED FILE");
        goto finish;
    }
    /* Prefetch first pattern before enabling HDMI playback. */
    (void)mod_patterns_get(NULL,s_ctx.song.patterntable[0],fmt.channels);
    if(mod_patterns_faults()) {
        osd_log("MOD: PAT CACHE INVALID");
        goto finish;
    }

    /* Each line stays below the 39-character Apple II OSD limit.
     * HEAP SAVED is the old contiguous header+patterns allocation. */
    osd_log("MOD FPGA PAT=%luB SMP=%luB",
            (unsigned long)fmt.pattern_bytes,
            (unsigned long)fmt.sample_bytes);
    osd_log("MOD MCU CACHE=%luB SAVED=%luB",
            (unsigned long)MOD_PATTERN_CACHE_BYTES,
            (unsigned long)fmt.prefix_bytes);
    osd_log("MOD SMP CACHE=8x%uB", (unsigned)MOD_STORE_PAGE);
#if MOD_STORE_PAGE==8192u && MOD_STORE_FETCH_BYTES==2048u
    /* Fixed binary signature allows guarded Stage2 wrapper to reject
     * accidental stale/8KiB-page builds. */
    osd_log("MOD SMP WIN=4x2048B");
    osd_log("MOD LOG=QUIET1HZ");
    osd_log("MOD JUKE=STARTFILE");
#else
    osd_log("MOD SMP WIN=%ux%uB",
            (unsigned)MOD_STORE_WINDOWS,(unsigned)MOD_STORE_FETCH_BYTES);
#endif
#if FPGA_SPI_MOD_BULK_XFER && !FPGA_SPI_MOD_BULK_SDRAM
    osd_log("MOD SPI=PCM512 SDRAM=BYTE");
#elif FPGA_SPI_MOD_BULK_XFER && FPGA_SPI_MOD_BULK_SDRAM
    osd_log("MOD SPI=BULK512 SDRAM=RISK");
#else
    osd_log("MOD SPI=BYTEWISE");
#endif
    osd_log("MOD %uCH PATS=%u HDR=%lu",
            (unsigned)fmt.channels,(unsigned)fmt.pattern_count,
            (unsigned long)fmt.header_bytes);
    ok=true;
finish:
    if(opened) {
        memset(&fs,0,sizeof fs);
        fs.op=FSOP_MOD_CLOSE;
        (void)disk_fs_request(&fs);
    }
    if(!ok) {
        hxcmod_unload(&s_ctx);
        mod_patterns_invalidate();
        mod_store_invalidate();
    }
    return ok;
}
/* J1: a complete MOD order-list pass ends on the HxCMOD song_wraps
 * event. HxCMOD still renders classic effect loops faithfully; the
 * wrap marker lets the host decide when to advance or stop. */
/* J2R8: instrument the critical path. RMAX includes HxCMOD's
 * per-voice sample-cache SPI fetches; SMAX is the 1-KiB FIFO upload.
 * DMIS counts misses within a 256-frame block, not over the song. */
static uint32_t s_rmax_us,s_smax_us,s_gmax_us,s_dmis_max;
static uint32_t s_min_level=PCM_FIFO_FRAMES;
static void pcm_perf_reset(void)
{
    s_rmax_us=s_smax_us=s_gmax_us=s_dmis_max=0u;
    s_min_level=PCM_FIFO_FRAMES;
}
static bool pcm_send_block(bool one_pass)
{
    const uint32_t wraps=s_ctx.song_wraps;
    const uint32_t miss_before=mod_store_misses();
    const uint64_t t0=bflb_mtimer_get_time_us();
    hxcmod_fillbuffer(&s_ctx,s_pcm,PCM_BLOCK_FRAMES,NULL);
    const uint64_t t1=bflb_mtimer_get_time_us();
    mod_gain_apply((int16_t *)s_pcm,PCM_BLOCK_FRAMES);
    const uint64_t t2=bflb_mtimer_get_time_us();
    fpga_spi_xfer_write(PCM_SPACE,0,(const uint8_t*)s_pcm,PCM_BLOCK_BYTES);
    const uint64_t t3=bflb_mtimer_get_time_us();
    const uint32_t r=(uint32_t)(t1-t0),g=(uint32_t)(t2-t1),spi=(uint32_t)(t3-t2);
    const uint32_t misses=mod_store_misses()-miss_before;
    if(r>s_rmax_us)s_rmax_us=r;
    if(g>s_gmax_us)s_gmax_us=g;
    if(spi>s_smax_us)s_smax_us=spi;
    if(misses>s_dmis_max)s_dmis_max=misses;
    return one_pass && s_ctx.song_wraps!=wraps;
}
static bool start_song(const char *path,unsigned track,unsigned total)
{
    s_state=MOD_PCM_LOADING;
    if(!pcm_read_status()) {
        osd_log("MCU MOD: NEED DIRECT PCM FPGA (SPACE6 PC V1)");
        s_state=MOD_PCM_ERROR;
        return false;
    }
    if(!player_load(path)) {
        s_state=MOD_PCM_ERROR;
        return false;
    }
    memcpy(s_last_request,path,strlen(path)+1u);
    __atomic_store_n(&s_has_last,1u,__ATOMIC_RELEASE);
    pcm_control(PCM_CTRL_RESET,0xA5u);
    mod_gain_reset(); /* clear previous track's limiter envelope */
    pcm_perf_reset();
    pcm_control(PCM_CTRL_ENABLE,1u);
    s_state=MOD_PCM_PLAYING;
    mod_now_playing_publish(path,track,total);
    osd_log("MCU MOD: PLAY %s",path);
    return true;
}
static bool playlist_play(unsigned *idx,unsigned start)
{
    const unsigned count=mod_jukebox_count();
    for(unsigned i=start;i<count;i++) {
        const char *path=mod_jukebox_track(i);
        if(path && start_song(path,i+1u,count)) {
            *idx=i;
            __atomic_store_n(&s_juke_last_track_pub,i+1u,__ATOMIC_RELEASE);
            osd_log("MCU JUKE: TRACK %u/%u",i+1u,count);
            return true;
        }
        osd_log("MCU JUKE: SKIP TRACK %u",i+1u);
    }
    return false;
}
void mod_audio_task(void *arg)
{
    char requested[MOD_PATH_CAP],jukedir[MOD_PATH_CAP];
    char juke_start_file[MOD_PATH_CAP];
    bool playing=false,draining=false,juke_active=false,recursive=false;
    unsigned juke_index=0;
    uint32_t blocks=0,window=0;
    (void)arg;
    s_state=MOD_PCM_IDLE;
    mod_now_playing_clear();
    osd_log("MCU MOD: DIRECT HxCMOD->HDMI READY");
    for(;;) {
        const bool selected=take_pending(requested);
        const bool jukebox=take_juke(jukedir,&recursive,juke_start_file);
        const bool resume=__atomic_exchange_n(&s_resume,0u,__ATOMIC_ACQ_REL)!=0u;
        const bool replay=__atomic_exchange_n(&s_replay,0u,__ATOMIC_ACQ_REL)!=0u;
        const uint32_t nav=__atomic_exchange_n(&s_nav,0u,__ATOMIC_ACQ_REL);
        const bool stop=__atomic_exchange_n(&s_stop,0u,__ATOMIC_ACQ_REL)!=0u;
        if(stop) {
            if(playing){player_release();playing=false;}
            mod_now_playing_clear();
            draining=false;
            juke_active=false;  /* list is retained for NEXT/PREV */
            s_state=MOD_PCM_STOPPED;
            osd_log("MCU MOD: PCM STOPPED");
        }else if(jukebox) {
            juke_state(MOD_JUKE_SCANNING);
            if(playing){player_release();playing=false;}
            mod_now_playing_clear();
            draining=false;
            juke_active=false;
            if(jukedir[0]=='\001' && jukedir[1]==0) {
                /* Work from the last successfully loaded MOD's folder. */
                const char *slash=strrchr(s_last_request,'/');
                if(s_has_last && slash) {
                    size_t n=(size_t)(slash-s_last_request);
                    memcpy(jukedir,s_last_request,n);
                    jukedir[n]=0;
                }else jukedir[0]=0; /* FAT root */
            }
            __atomic_store_n(&s_juke_count_pub,0u,__ATOMIC_RELEASE);
            __atomic_store_n(&s_juke_last_track_pub,0u,__ATOMIC_RELEASE);
            osd_log("MCU JUKE: SCAN %s %s",recursive?"TREE":"FOLDER",
                    jukedir[0]?jukedir:"/");
            if(mod_jukebox_scan(jukedir,recursive)) {
                __atomic_store_n(&s_juke_count_pub,mod_jukebox_count(),__ATOMIC_RELEASE);
                juke_state(MOD_JUKE_READY);
                int first=0;
                if(juke_start_file[0])
                    first=mod_jukebox_find(juke_start_file);
                if(first<0) {
                    /* Filesystem may have changed since the user picked
                     * a track. Never silently restart at the first MOD. */
                    juke_active=false;
                    playing=false;
                    s_state=MOD_PCM_STOPPED;
                    mod_jukebox_clear();
                    __atomic_store_n(&s_juke_count_pub,0u,__ATOMIC_RELEASE);
                    juke_state(MOD_JUKE_START_MISSING);
                    osd_log("MCU JUKE: START MOD NOT FOUND");
                } else {
                    juke_index=(unsigned)first;
                    juke_active=playlist_play(&juke_index,(unsigned)first);
                    playing=juke_active;
                }
            }else {
                juke_state(MOD_JUKE_EMPTY);
                s_state=MOD_PCM_STOPPED;
                osd_log("MCU JUKE: NO .MOD FILES FOUND");
            }
            blocks=window=0;
        }else if(selected) {
            if(playing){player_release();playing=false;}
            mod_now_playing_clear();
            draining=false;
            juke_active=false;
            mod_jukebox_clear();
            __atomic_store_n(&s_juke_count_pub,0u,__ATOMIC_RELEASE);
            __atomic_store_n(&s_juke_last_track_pub,0u,__ATOMIC_RELEASE);
            juke_state(MOD_JUKE_IDLE);
            playing=start_song(requested,0u,0u);
            blocks=window=0;
        }else if(resume && mod_jukebox_count() && !playing) {
            draining=false;
            juke_active=playlist_play(&juke_index,juke_index);
            playing=juke_active;
            blocks=window=0;
        }else if(nav && mod_jukebox_count()) {
            unsigned target;
            const unsigned count=mod_jukebox_count();
            if(playing){player_release();playing=false;}
            mod_now_playing_clear();
            draining=false;
            target=(nav==1u)?(juke_index+1u)%count:
                              (juke_index?juke_index-1u:count-1u);
            juke_active=playlist_play(&juke_index,target);
            /* NEXT wraps around if last items are unloadable. */
            if(!juke_active && target!=0)
                juke_active=playlist_play(&juke_index,0);
            playing=juke_active;
            blocks=window=0;
        }else if(replay && __atomic_load_n(&s_has_last,__ATOMIC_ACQUIRE)) {
            if(playing){player_release();playing=false;}
            mod_now_playing_clear();
            draining=false;
            playing=start_song(s_last_request,0u,0u);
            blocks=window=0;
        }
        bool fast_refill=false;
        if(playing) {
            if(!pcm_read_status()) {
                osd_log("MCU MOD: FPGA PCM LINK LOST");
                player_release();playing=false;
                mod_now_playing_clear();
                draining=false;juke_active=false;
                s_state=MOD_PCM_ERROR;
            }else if(draining) {
                /* Let existing FPGA PCM frames finish before clearing FIFO.
                 * Hardware may count one intentional underrun at song end. */
                if(pcm_free()>=2048u) {
                    player_release();
                    playing=false;
                    mod_now_playing_clear();
                    draining=false;
                    if(juke_active && juke_index+1u<mod_jukebox_count()) {
                        juke_active=playlist_play(&juke_index,juke_index+1u);
                        playing=juke_active;
                        blocks=window=0;
                    }else {
                        juke_active=false; /* reached last track, do not loop */
                        s_state=MOD_PCM_STOPPED;
                        osd_log("MCU JUKE: FINISHED / PLAY ONCE DONE");
                    }
                }
            }else if(pcm_free()>=PCM_BLOCK_FRAMES) {
                const uint16_t available=pcm_free();
                /* Measure FIFO low-water after startup buffering. */
                if(blocks>=8u) {
                    const uint16_t level=(uint16_t)(PCM_FIFO_FRAMES-available);
                    if(level<s_min_level)s_min_level=level;
                }
                const bool done=pcm_send_block(juke_active || mod_audio_play_once());
                /* Refill promptly if three blocks will fit. Preserve the
                 * priority of HID/USB and yield to equal-priority speech. */
                fast_refill=(!done && available>=PCM_BLOCK_FRAMES*3u);
                ++blocks;
                if(done) {
                    draining=true;
                    osd_log("MCU MOD: SONG COMPLETE (ORDER WRAP)");
                }
                // J2R10: preserve useful MOD counters, but snapshot every
                // ~8.9s (1536 x 256 frames), not every ~2.2s. Console
                // updates are queued in SRAM and repainted at 1Hz max.
                // No SPI/OSD traffic is generated by this telemetry.
                if(++window>=1536u) {
                    osd_log("MOD %uCH FRAMES=%lu FREE=%u",
                            (unsigned)s_ctx.number_of_channels,
                            (unsigned long)(blocks*PCM_BLOCK_FRAMES),
                            (unsigned)pcm_free());
                    osd_log("UDR=%u MIS=%lu ERR=%lu",
                            (unsigned)pcm_underruns(),
                            (unsigned long)mod_store_misses(),
                            (unsigned long)mod_store_faults());
                    /* One diagnostic batch per 8.9s, no repetitive screens. */
                        osd_log("PCM RMAX=%lu SMAX=%lu",
                                (unsigned long)s_rmax_us,
                                (unsigned long)s_smax_us);
                        osd_log("PCM GMAX=%lu DMIS=%lu LOW=%lu",
                                (unsigned long)s_gmax_us,
                                (unsigned long)s_dmis_max,
                                (unsigned long)s_min_level);
                        osd_log("SMP SPI B=%lu PG=%u",
                                (unsigned long)mod_store_read_bytes(),
                                (unsigned)MOD_STORE_FETCH_BYTES);
                        osd_log("PF=%lu B=%lu E=%lu",
                                (unsigned long)mod_patterns_fetch_count(),
                                (unsigned long)mod_patterns_read_bytes(),
                                (unsigned long)mod_patterns_faults());
                        osd_log("PH=%lu EV=%lu",
                                (unsigned long)mod_patterns_cache_hits(),
                                (unsigned long)mod_patterns_evictions());
                    window=0;
                }
            }
        }
        if(fast_refill) {
            taskYIELD();
        }else {
            vTaskDelay(pdMS_TO_TICKS(1));
        }
    }
}
